import json
import re
from docx import Document

# Load data
with open('/root/employee_data.json') as f:
    data = json.load(f)

doc = Document('/root/offer_letter_template.docx')

PLACEHOLDER_RE = re.compile(r'\{\{([A-Z_]+)\}\}')


def replace_in_para(para):
    """Replace all {{KEY}} placeholders in a paragraph, handling split runs."""
    text = para.text
    if '{{' not in text:
        return

    # Handle conditional markers first
    # Since RELOCATION_PACKAGE == "Yes", keep content, remove IF/END_IF markers
    relocation = data.get('RELOCATION_PACKAGE', 'No').strip().lower() == 'yes'
    if '{{IF_RELOCATION}}' in text:
        if relocation:
            text = text.replace('{{IF_RELOCATION}}', '').replace('{{END_IF_RELOCATION}}', '')
        else:
            # Find text between markers and remove it entirely
            text = re.sub(r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}', '', text, flags=re.DOTALL)

    # Replace all remaining placeholders
    def replacer(m):
        key = m.group(1)
        return str(data[key]) if key in data else m.group(0)

    new_text = PLACEHOLDER_RE.sub(replacer, text)

    if new_text != para.text and para.runs:
        para.runs[0].text = new_text
        for run in para.runs[1:]:
            run.text = ''


def process_table(table):
    """Recursively process tables including nested ones."""
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                replace_in_para(para)
            for nested in cell.tables:
                process_table(nested)


# Main document paragraphs
for para in doc.paragraphs:
    replace_in_para(para)

# All tables (including nested via recursion)
for table in doc.tables:
    process_table(table)

# Headers and footers
for section in doc.sections:
    for para in section.header.paragraphs:
        replace_in_para(para)
    for para in section.footer.paragraphs:
        replace_in_para(para)

doc.save('/root/offer_letter_filled.docx')
print("Saved: /root/offer_letter_filled.docx")

